using System.Windows;using System.Windows.Controls;using LibraryManager.Views; namespace LibraryManager; public partial class MainWindow:Window { public MainWindow(){InitializeComponent();Host.Content=new BooksView();} void Navigate(object s,RoutedEventArgs e){Host.Content=((Button)s).Tag.ToString() switch{"Books"=>new BooksView(),"Members"=>new MembersView(),"Loans"=>new LoanRegisterView(),"Returns"=>new LoanReturnView(),"Fines"=>new UnpaidFinesView(),"Reports"=>new ReportsView(),"Backup"=>new BackupView(),_=>new SettingsView()};} }